ops_config research_repo_target holds a value other than auto, legacy or consolidated, which the resolver reads as auto'' WHEN NOT EXISTS (SELECT 1 FROM cloud_ops_events WHERE kind = ''repo-sync'' AND status IN (''ok'', ''warn'') AND ts > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-10080 minutes'')) AND lower(trim(COALESCE((SELECT value FROM ops_config WHERE key = ''research_repo_target''), ''auto''))) <> ''legacy'' THEN ''no repo-sync event in 7 days while the target is not legacy, so the 10-minute sync tick that the switches guard has not run'' ELSE ''ok'' END AS observed'; UPDATE control_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM ops_config WHERE key IN (''breach_doctor_max_cases'', ''breach_doctor_max_actions'', ''breach_doctor_budget_ms'')) < 3 THEN ''an ops_config row of the three doctor caps (breach_doctor_max_cases, breach_doctor_max_actions, breach_doctor_budget_ms) is missing, so the bound is not a lever'' WHEN EXISTS (SELECT 1 FROM ops_config WHERE (key = ''breach_doctor_max_cases'' AND NOT (CAST(value AS INTEGER) BETWEEN 1 AND 60)) OR (key = ''breach_doctor_max_actions'' AND NOT (CAST(value AS INTEGER) BETWEEN 0 AND 20)) OR (key = ''breach_doctor_budget_ms'' AND NOT (CAST(value AS INTEGER) BETWEEN 5000 AND 40000))) THEN ''a doctor cap is outside the range bdConfig accepts (cases 1 to 60, actions 0 to 20, budget 5000 to 40000 ms), so the engine reads its default instead'' WHEN COALESCE((SELECT value FROM ops_config WHERE key = ''breach_doctor''), ''measure'') <> ''off'' AND COALESCE((SELECT MAX(ts) FROM breach_diagnosis_events WHERE event = ''tick''), '''') < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-30 minutes'') THEN ''the doctor wrote no tick event in 30 minutes while it is not switched off, so a cap that should only delay work has stopped the loop'' ELSE ''ok'' END AS observed' WHERE control = 'breach-doctor-caps' AND probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM ops_config WHERE key IN (''breach_doctor_max_cases'', ''breach_doctor_max_actions'', ''breach_doctor_budget_ms'')) < 3 THEN ''an ops_config row of the three doctor caps (breach_doctor_max_cases, breach_doctor_max_actions, breach_doctor_budget_ms) is missing, so the bound is not a lever'' WHEN EXISTS (SELECT 1 FROM ops_config WHERE (key = ''breach_doctor_max_cases'' AND NOT (CAST(value AS INTEGER) BETWEEN 1 AND 60)) OR (key = ''breach_doctor_max_actions'' AND NOT (CAST(value AS INTEGER) BETWEEN 0 AND 20)) OR (key = ''breach_doctor_budget_ms'' AND NOT (CAST(value AS INTEGER) BETWEEN 5000 AND 40000))) THEN ''a doctor cap is outside the range bdConfig accepts (cases 1 to 60, actions 0 to 20, budget 5000 to 40000 ms), so the engine clamps it'' WHEN lower(trim(COALESCE((SELECT value FROM ops_config WHERE key = ''breach_doctor''), ''measure''))) NOT IN (''off'', ''0'', ''false'', ''no'', ''disabled'') AND COALESCE((SELECT MAX(ts) FROM breach_diagnosis_events WHERE event = ''tick''), '''') < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-30 minutes'') THEN ''the doctor wrote no tick event in 30 minutes while it is not switched off, so a cap that should only delay work has stopped the loop'' ELSE ''ok'' END AS observed'; UPDATE control_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN COALESCE((SELECT last_refreshed FROM metric_registry WHERE metric = ''doctor_taint_violations_24h''), '''') < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-180 minutes'') THEN ''the doctor_taint_violations_24h metric is missing or was not refreshed in 3 hours, so a refused free-text fact would go unreported'' WHEN NOT EXISTS (SELECT 1 FROM ops_config WHERE key = ''code_merge_trusted_sources'') THEN ''the ops_config row code_merge_trusted_sources is missing, so the trusted-source list the guard relies on is unreadable'' WHEN instr('','' || COALESCE((SELECT value FROM ops_config WHERE key = ''code_merge_trusted_sources''), '''') || '','', '',*,'') > 0 OR instr('','' || COALESCE((SELECT v