e is no longer 120 minutes (the SLA-120M-1 ceiling)'' WHEN COALESCE((SELECT value FROM ops_config WHERE key = ''breach_doctor''), ''measure'') NOT IN (''on'', ''measure'', ''off'') THEN ''ops_config breach_doctor holds a value other than on, measure or off, so the lever that removes the gate without a deploy is unreadable'' WHEN NOT EXISTS (SELECT 1 FROM analytics_action_log WHERE status = ''recovered'' AND fired_at > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-10080 minutes'')) THEN ''the evaluator closed no recovered METRIC-TRIGGER issue in 7 days, so the TRIGGER-RECOVERY-1 path that the gate defers to is not running'' ELSE ''ok'' END AS observed' WHERE control = 'metric-playbook-recovery-hold' AND probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''MD-4'' AND instr(trigger_sql, ''* 1440 >= '') > 0 AND CAST(substr(trigger_sql, instr(trigger_sql, ''* 1440 >= '') + 10, 4) AS INTEGER) BETWEEN 1 AND 120) THEN ''the MD-4 rule is missing or its recovery gate is not between 1 and 120 minutes (the SLA-120M-1 ceiling)'' WHEN lower(trim(COALESCE((SELECT value FROM ops_config WHERE key = ''breach_doctor''), ''measure''))) NOT IN (''on'', ''measure'', ''off'', ''0'', ''false'', ''no'', ''disabled'') THEN ''ops_config breach_doctor holds a value the engine does not read as on, measure or off, so the lever that removes the gate without a deploy is unreadable'' WHEN NOT EXISTS (SELECT 1 FROM analytics_action_log WHERE status = ''recovered'' AND fired_at > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-10080 minutes'')) THEN ''the evaluator closed no recovered METRIC-TRIGGER issue in 7 days, so the TRIGGER-RECOVERY-1 path that the gate defers to is not running'' ELSE ''ok'' END AS observed'; UPDATE control_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''PN-R2'' AND enabled = 1) THEN ''the PN-R2 rule is missing or disabled, so the enabled switch that stops it is not a lever'' WHEN EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''PN-R2'' AND instr(trigger_sql, ''1440'') > 0) THEN ''the PN-R2 trigger carries a 1440-minute window again, which SLA-120M-1 forbids'' WHEN EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''PN-R2'' AND instr(trigger_sql, ''BREACH-DOCTOR-1: PN-R2 qnfo-fleet-control'') = 0) THEN ''the PN-R2 trigger no longer reads the lever issue BREACH-DOCTOR-1: PN-R2 qnfo-fleet-control, so the gate has no release condition'' WHEN EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''PN-R2'' AND instr(verify_sql, ''pn-reopened'') = 0) THEN ''the PN-R2 verify no longer reads pn-reopened, so a close that the filer undoes is not counted'' ELSE ''ok'' END AS observed' WHERE control = 'pn-r2-filer-quiet-gate' AND probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''PN-R2'') THEN ''the PN-R2 rule is missing, so the enabled switch that stops it has no row to switch'' WHEN EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''PN-R2'' AND (instr(trigger_sql, ''1440 minutes'') > 0 OR instr(trigger_sql, ''24 hours'') > 0)) THEN ''the PN-R2 trigger carries a 24-hour quiet window again, which SLA-120M-1 forbids'' WHEN EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''PN-R2'' AND instr(trigger_sql, ''BREACH-DOCTOR-1: PN-R2 qnfo-fleet-control'') = 0) THEN ''the PN-R2 trigger no longer reads the lever issue BREACH-DOCTOR-1: PN-R2 qnfo-fleet-control, so the gate has no release condition'' WHEN EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''PN-R2'' AND instr(verify_sql, ''pn-reopened'') = 0) THEN ''the PN-R2 verify no longer reads pn-reopened, so a close that the filer undoes is not counted'' ELSE ''ok'' END AS observed'; UPDATE control_alternate_probes SET window_note = replace(window_note, ' | CONTROL-ALT-PROBES-4D 2026-10-26: recalibrated after an independent review of the 18 probes against the loops they describe: a disabled playbook row is the documented lever and no longer reads as a failure (the clauses read that the row exists), the clauses that need the doctor tick are skipped while ops_config breach_doctor is off in any spelling the engine reads (off, 0, false, no, disabled), the research flags are read without case and space as the worker reads them, and the sync tick check is skipped while the target is legacy.', '') WHERE control IN ('research-repo-archive-gate', 'research-repo-sync-switches', 'breach-doctor-caps', 'breach-doctor-taint-guard', 'breach-doctor-gap-measure', 'breach-doctor-gap-caps', 'breach-doctor-rearm-capacity', 'breach-doctor-auto-demotion', 'breach-doctor-tool-exclusion-rule', 'metric-playbook-recovery-hold', 'pn-r2-filer-quiet-gate')
-- Rollback note: decision_log stays (append-only).

CREATE TABLE IF NOT EXISTS bak_20261026_control_probes4d AS
  SELECT control, probe_sql AS old_probe_sql, window_note AS old_window_note FROM control_alternate_probes WHERE control IN ('research-repo-archive-gate', 'research-repo-sync-switches', 'breach-doctor-caps', 'breach-doctor-taint-guard', 'breach-doctor-gap-measure', 'breach-doctor-gap-caps', 'breach-doctor-rearm-capacity', 'breach-doctor-auto-demotion', 'breach-doctor-tool-exclusion-rule', 'metric-playbook-recovery-hold', 'pn-r2-filer-quiet-gate');

UPDATE control_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM ops_config WHERE key = ''research_repo_archive'') = 0 THEN ''the ops_config row research_repo_archive is missing, so the off lever cannot be set'' WHEN lower(trim((SELECT value FROM ops_config WHERE key = ''research_repo_archive''))) NOT IN (''on'', ''off'') THEN ''ops_config research_repo_archive holds a value other than on or off (the worker ignores case and spaces), so the off lever is unreadable'' WHEN EXISTS (SELECT 1 FROM portfolio_actions WHERE action = ''archive-request'' AND repo IN (''QNFO/qnfo-ensemble-research'', ''qnfo-ensemble-research'')) AND (SELECT COUNT(*) FROM research_run_ledger WHERE status = ''ok'' AND repo = ''QNFO/qnfo-research'') < 3 THEN ''an archive request for the legacy ensemble repository exists while research_run_ledger holds fewer than 3 consolidated deposits, so the gate did not hold'' ELSE ''ok'' END AS observed'
WHERE control = 'research-repo-archive-gate' AND probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM ops_config WHERE key = ''research_repo_archive'') = 0 THEN ''the ops_config row research_repo_archive is missing, so the off lever cannot be set'' WHEN (SELECT value FROM ops_config WHERE key = ''research_repo_archive'') NOT IN (''on'', ''off'') THEN ''ops_config research_repo_archive holds a value other than on or off, and only the exact value off stops the archive request'' WHEN EXISTS (SELECT 1 FROM portfolio_actions WHERE action = ''archive-request'' AND repo IN (''QNFO/qnfo-ensemble-research'', ''qnfo-ensemble-research'')) AND (SELECT COUNT(*) FROM research_run_ledger WHERE status = ''ok'' AND repo = ''QNFO/qnfo-research'') < 3 THEN ''an archive request for the legacy ensemble repository exists while research_run_ledger holds fewer than 3 consolidated deposits, so the gate did not hold'' ELSE ''ok'' END AS observed';

UPDATE control_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM ops_config WHERE key IN (''research_repo_sync'', ''research_repo_restore'', ''research_repo_target'')) < 3 THEN ''an ops_config row of the three repo levers (research_repo_sync, research_repo_restore, research_repo_target) is missing, so a switch cannot be set'' WHEN EXISTS (SELECT 1 FROM ops_config WHERE key IN (''research_repo_sync'', ''research_repo_restore'') AND lower(trim(value)) NOT IN (''on'', ''off'')) THEN ''research_repo_sync or research_repo_restore holds a value other than on or off (the worker ignores case and spaces), so that step of the tick cannot be switched'' WHEN lower(trim((SELECT value FROM ops_config WHERE key = ''research_repo_target''))) NOT IN (''auto'', ''legacy'', ''consolidated'') THEN ''ops_config research_repo_target holds a value other than auto, legacy or consolidated, which the resolver reads as auto'' WHEN NOT EXISTS (SELECT 1 FROM cloud_ops_events WHERE kind = ''repo-sync'' AND status IN (''ok'', ''warn'') AND ts > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-10080 minutes'')) AND lower(trim(COALESCE((SELECT value FROM ops_config WHERE key = ''research_repo_target''), ''auto''))) <> ''legacy'' THEN ''no repo-sync event in 7 days while the target is not legacy, so the 10-minute sync tick that the switches guard has not run'' ELSE ''ok'' END AS observed'
WHERE control = 'research-repo-sync-switches' AND probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM ops_config WHERE key IN (''research_repo_sync'', ''research_repo_restore'', ''research_repo_target'')) < 3 THEN ''an ops_config row of the three repo levers (research_repo_sync, research_repo_restore, research_repo_target) is missing, so a switch cannot be set'' WHEN EXISTS (SELECT 1 FROM ops_config WHERE key IN (''research_repo_sync'', ''research_repo_restore'') AND value NOT IN (''on'', ''off'')) THEN ''research_repo_sync or research_repo_restore holds a value other than on or off, and only the exact value off stops that step of the tick'' WHEN (SELECT value FROM ops_config WHERE key = ''research_repo_target'') NOT IN (''auto'', ''legacy'', ''consolidated'') THEN ''ops_config research_repo_target holds a value other than auto, legacy or consolidated, which the resolver reads as auto'' WHEN NOT EXISTS (SELECT 1 FROM cloud_ops_events WHERE kind = ''repo-sync'' AND status IN (''ok'', ''warn'') AND ts > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-10080 minutes'')) THEN ''no repo-sync event in 7 days, so the 10-minute sync tick that the switches guard has not run'' ELSE ''ok'' END AS observed';

UPDATE control_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM ops_config WHERE key IN (''breach_doctor_max_cases'', ''breach_doctor_max_actions'', ''breach_doctor_budget_ms'')) < 3 THEN ''an ops_config row of the three doctor caps (breach_doctor_max_cases, breach_doctor_max_actions, breach_doctor_budget_ms) is missing, so the bound is not a lever'' WHEN EXISTS (SELECT 1 FROM ops_config WHERE (key = ''breach_doctor_max_cases'' AND NOT (CAST(value AS INTEGER) BETWEEN 1 AND 60)) OR (key = ''breach_doctor_max_actions'' AND NOT (CAST(value AS INTEGER) BETWEEN 0 AND 20)) OR (key = ''breach_doctor_budget_ms'' AND NOT (CAST(value AS INTEGER) BETWEEN 5000 AND 40000))) THEN ''a doctor cap is outside the range bdConfig accepts (cases 1 to 60, actions 0 to 20, budget 5000 to 40000 ms), so the engine clamps it'' WHEN lower(trim(COALESCE((SELECT value FROM ops_config WHERE key = ''breach_doctor''), ''measure''))) NOT IN (''off'', ''0'', ''false'', ''no'', ''disabled'') AND COALESCE((SELECT MAX(ts) FROM breach_diagnosis_events WHERE event = ''tick''), '''') < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-30 minutes'') THEN ''the doctor wrote no tick event in 30 minutes while it is not switched off, so a cap that should only delay work has stopped the loop'' ELSE ''ok'' END AS observed'
WHERE control = 'breach-doctor-caps' AND probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM ops_config WHERE key IN (''breach_doctor_max_cases'', ''breach_doctor_max_actions'', ''breach_doctor_budget_ms'')) < 3 THEN ''an ops_config row of the three doctor caps (breach_doctor_max_cases, breach_doctor_max_actions, breach_doctor_budget_ms) is missing, so the bound is not a lever'' WHEN EXISTS (SELECT 1 FROM ops_config WHERE (key = ''breach_doctor_max_cases'' AND NOT (CAST(value AS INTEGER) BETWEEN 1 AND 60)) OR (key = ''breach_doctor_max_actions'' AND NOT (CAST(value AS INTEGER) BETWEEN 0 AND 20)) OR (key = ''breach_doctor_budget_ms'' AND NOT (CAST(value AS INTEGER) BETWEEN 5000 AND 40000))) THEN ''a doctor cap is outside the range bdConfig accepts (cases 1 to 60, actions 0 to 20, budget 5000 to 40000 ms), so the engine reads its default instead'' WHEN COALESCE((SELECT value FROM ops_config WHERE key = ''breach_doctor''), ''measure'') <> ''off'' AND COALESCE((SELECT MAX(ts) FROM breach_diagnosis_events WHERE event = ''tick''), '''') < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-30 minutes'') THEN ''the doctor wrote no tick event in 30 minutes while it is not switched off, so a cap that should only delay work has stopped the loop'' ELSE ''ok'' END AS observed';

UPDATE control_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN lower(trim(COALESCE((SELECT value FROM ops_config WHERE key = ''breach_doctor''), ''measure''))) NOT IN (''off'', ''0'', ''false'', ''no'', ''disabled'') AND COALESCE((SELECT last_refreshed FROM metric_registry WHERE metric = ''doctor_taint_violations_24h''), '''') < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-180 minutes'') THEN ''the doctor_taint_violations_24h metric is missing or was not refreshed in 3 hours while the doctor is not switched off, so a refused free-text fact would go unreported'' WHEN NOT EXISTS (SELECT 1 FROM ops_config WHERE key = ''code_merge_trusted_sources'') THEN ''the ops_config row code_merge_trusted_sources is missing, so the trusted-source list the guard relies on is unreadable'' WHEN instr('','' || COALESCE((SELECT value FROM ops_config WHERE key = ''code_merge_trusted_sources''), '''') || '','', '',*,'') > 0 OR instr('','' || COALESCE((SELECT value FROM ops_config WHERE key = ''code_merge_trusted_sources''), '''') || '','', '',*|'') > 0 THEN ''code_merge_trusted_sources holds a global wildcard entry, so every source is trusted and the guard protects nothing'' ELSE ''ok'' END AS observed'
WHERE control = 'breach-doctor-taint-guard' AND probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN COALESCE((SELECT last_refreshed FROM metric_registry WHERE metric = ''doctor_taint_violations_24h''), '''') < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-180 minutes'') THEN ''the doctor_taint_violations_24h metric is missing or was not refreshed in 3 hours, so a refused free-text fact would go unreported'' WHEN NOT EXISTS (SELECT 1 FROM ops_config WHERE key = ''code_merge_trusted_sources'') THEN ''the ops_config row code_merge_trusted_sources is missing, so the trusted-source list the guard relies on is unreadable'' WHEN instr('','' || COALESCE((SELECT value FROM ops_config WHERE key = ''code_merge_trusted_sources''), '''') || '','', '',*,'') > 0 OR instr('','' || COALESCE((SELECT value FROM ops_config WHERE key = ''code_merge_trusted_sources''), '''') || '','', '',*|'') > 0 THEN ''code_merge_trusted_sources holds a global wildcard entry, so every source is trusted and the guard protects nothing'' ELSE ''ok'' END AS observed';

UPDATE control_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''playbook-gap'' AND mode = ''measure'') THEN ''the playbook-gap rule is missing or no longer in measure, so the hold this control records was lifted without the register being updated'' WHEN NOT EXISTS (SELECT 1 FROM sqlite_master WHERE type = ''view'' AND name = ''v_breach_doctor_status'' AND instr(sql, ''unclassified_cases'') > 0 AND instr(sql, ''gap_families'') > 0 AND instr(sql, ''gap_by_family'') > 0) THEN ''v_breach_doctor_status no longer reports unclassified_cases, gap_families and gap_by_family, so the gap is hidden'' WHEN NOT EXISTS (SELECT 1 FROM metric_registry WHERE metric = ''breaches_undiagnosed_over_60m'') OR NOT EXISTS (SELECT 1 FROM analytics_metric_triggers WHERE metric_key = ''breaches_undiagnosed_over_60m'' AND enabled = 1) THEN ''the breaches_undiagnosed_over_60m metric or its enabled trigger is missing, so nobody is told about the gap'' ELSE ''ok'' END AS observed'
WHERE control = 'breach-doctor-gap-measure' AND probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''playbook-gap'' AND enabled = 1) THEN ''the playbook-gap row is missing or disabled, so the switch for the gap issues is not a lever'' WHEN NOT EXISTS (SELECT 1 FROM sqlite_master WHERE type = ''view'' AND name = ''v_breach_doctor_status'' AND instr(sql, ''unclassified_cases'') > 0 AND instr(sql, ''gap_families'') > 0 AND instr(sql, ''gap_by_family'') > 0) THEN ''v_breach_doctor_status no longer reports unclassified_cases, gap_families and gap_by_family, so the gap is hidden'' WHEN NOT EXISTS (SELECT 1 FROM metric_registry WHERE metric = ''breaches_undiagnosed_over_60m'') OR NOT EXISTS (SELECT 1 FROM analytics_metric_triggers WHERE metric_key = ''breaches_undiagnosed_over_60m'' AND enabled = 1) THEN ''the breaches_undiagnosed_over_60m metric or its enabled trigger is missing, so nobody is told about the gap'' ELSE ''ok'' END AS observed';

UPDATE control_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''playbook-gap'' AND max_per_tick BETWEEN 0 AND 12 AND max_per_day BETWEEN 0 AND 100) THEN ''the playbook-gap row is missing or has no bounded max_per_tick (0 to 12) and max_per_day (0 to 100), so the rate of gap issues is not bounded'' WHEN (SELECT COUNT(*) FROM agent_issues WHERE status = ''open'' AND title LIKE ''BREACH-DOCTOR-1: playbook gap %'') > 3 THEN ''more than 3 playbook gap issues are open, so BD_GAP_OPEN_MAX does not hold'' WHEN EXISTS (SELECT 1 FROM agent_issues WHERE status = ''open'' AND title LIKE ''BREACH-DOCTOR-1: playbook gap %'' AND substr(title, 31) IN (''OWNER-CHAT'', ''OWNER-REQUEST'', ''other'', ''BREACH-DOCTOR-1'')) THEN ''a playbook gap issue is open for a family no playbook can close (OWNER-CHAT, OWNER-REQUEST, other, BREACH-DOCTOR-1)'' ELSE ''ok'' END AS observed'
WHERE control = 'breach-doctor-gap-caps' AND probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''playbook-gap'' AND enabled = 1 AND max_per_tick BETWEEN 1 AND 12 AND max_per_day BETWEEN 1 AND 100) THEN ''the playbook-gap row is missing, disabled or has no bounded max_per_tick (1 to 12) and max_per_day (1 to 100), so the rate of gap issues is not bounded'' WHEN (SELECT COUNT(*) FROM agent_issues WHERE status = ''open'' AND title LIKE ''BREACH-DOCTOR-1: playbook gap %'') > 3 THEN ''more than 3 playbook gap issues are open, so BD_GAP_OPEN_MAX does not hold'' WHEN EXISTS (SELECT 1 FROM agent_issues WHERE status = ''open'' AND title LIKE ''BREACH-DOCTOR-1: playbook gap %'' AND substr(title, 31) IN (''OWNER-CHAT'', ''OWNER-REQUEST'', ''other'', ''BREACH-DOCTOR-1'')) THEN ''a playbook gap issue is open for a family no playbook can close (OWNER-CHAT, OWNER-REQUEST, other, BREACH-DOCTOR-1)'' ELSE ''ok'' END AS observed';

UPDATE control_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''TL-R01-rearm'') THEN ''the TL-R01-rearm rule is missing, so the enabled switch that stops it has no row to switch'' WHEN (SELECT COUNT(*) FROM breach_diagnoses WHERE rule_id = ''TL-R01-rearm'' AND state IN (''queued'', ''applied'', ''verifying'')) > 6 THEN ''more than 6 TL-R01-rearm cases are in flight, so the capacity cap does not hold'' WHEN EXISTS (SELECT 1 FROM ops_config WHERE key = ''code_plan_daily_cap'' AND value NOT GLOB ''[0-9]*'') THEN ''ops_config code_plan_daily_cap is not a number, so the rule trigger reads the default of 24 instead of the planner cap'' WHEN lower(trim(COALESCE((SELECT value FROM ops_config WHERE key = ''breach_doctor''), ''measure''))) NOT IN (''off'', ''0'', ''false'', ''no'', ''disabled'') AND EXISTS (SELECT 1 FROM breach_diagnoses WHERE rule_id = ''TL-R01-rearm'' AND state IN (''queued'', ''applied'', ''verifying'') AND lease_until < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-60 minutes'')) THEN ''a TL-R01-rearm case is more than 60 minutes past its 30-minute lease, so the lease expiry did not end it'' ELSE ''ok'' END AS observed'
WHERE control = 'breach-doctor-rearm-capacity' AND probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''TL-R01-rearm'' AND enabled = 1) THEN ''the TL-R01-rearm rule is missing or disabled, so the enabled switch that stops it is not a lever'' WHEN (SELECT COUNT(*) FROM breach_diagnoses WHERE rule_id = ''TL-R01-rearm'' AND state IN (''queued'', ''applied'', ''verifying'')) > 6 THEN ''more than 6 TL-R01-rearm cases are in flight, so the capacity cap does not hold'' WHEN EXISTS (SELECT 1 FROM ops_config WHERE key = ''code_plan_daily_cap'' AND value NOT GLOB ''[0-9]*'') THEN ''ops_config code_plan_daily_cap is not a number, so the rule trigger reads the default of 24 instead of the planner cap'' WHEN EXISTS (SELECT 1 FROM breach_diagnoses WHERE rule_id = ''TL-R01-rearm'' AND state IN (''queued'', ''applied'', ''verifying'') AND lease_until < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-60 minutes'')) THEN ''a TL-R01-rearm case is more than 60 minutes past its 30-minute lease, so the lease expiry did not end it'' ELSE ''ok'' END AS observed';

UPDATE control_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM remediation_contracts WHERE class = ''fm-breach-doctor-rule-latched'' AND status = ''active'') THEN ''the fm-breach-doctor-rule-latched detector contract is missing or not active, so a demotion that outlives its release would go unseen'' WHEN lower(trim(COALESCE((SELECT value FROM ops_config WHERE key = ''breach_doctor''), ''measure''))) NOT IN (''off'', ''0'', ''false'', ''no'', ''disabled'') AND EXISTS (SELECT 1 FROM breach_playbooks WHERE enabled = 1 AND mode = ''measure'' AND note LIKE ''demoted 20%'' AND substr(note, 9, 20) < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-120 minutes'')) THEN ''a playbook has stayed demoted to measure for over 120 minutes, so the automatic release after 60 minutes did not run'' WHEN NOT EXISTS (SELECT 1 FROM breach_playbooks WHERE enabled = 1 AND mode = ''on'') THEN ''no enabled playbook is in mode on, so the doctor acts on nothing and every rule reads as held'' ELSE ''ok'' END AS observed'
WHERE control = 'breach-doctor-auto-demotion' AND probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM remediation_contracts WHERE class = ''fm-breach-doctor-rule-latched'' AND status = ''active'') THEN ''the fm-breach-doctor-rule-latched detector contract is missing or not active, so a demotion that outlives its release would go unseen'' WHEN EXISTS (SELECT 1 FROM breach_playbooks WHERE enabled = 1 AND mode = ''measure'' AND note LIKE ''demoted 20%'' AND substr(note, 9, 20) < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-120 minutes'')) THEN ''a playbook has stayed demoted to measure for over 120 minutes, so the automatic release after 60 minutes did not run'' WHEN NOT EXISTS (SELECT 1 FROM breach_playbooks WHERE enabled = 1 AND mode = ''on'') THEN ''no enabled playbook is in mode on, so the doctor acts on nothing and every rule reads as held'' ELSE ''ok'' END AS observed';

