UPDATE control_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''MD-4'' AND instr(trigger_sql, ''* 1440 >= '') > 0 AND CAST(substr(trigger_sql, instr(trigger_sql, ''* 1440 >= '') + 10, 4) AS INTEGER) BETWEEN 1 AND 120) THEN ''the MD-4 rule is missing or its recovery gate is not between 1 and 120 minutes (the SLA-120M-1 ceiling)'' WHEN lower(trim(COALESCE((SELECT value FROM ops_config WHERE key = ''breach_doctor''), ''measure''))) NOT IN (''on'', ''measure'', ''off'', ''0'', ''false'', ''no'', ''disabled'') THEN ''ops_config breach_doctor holds a value the engine does not read as on, measure or off, so the lever that removes the gate without a deploy is unreadable'' WHEN NOT EXISTS (SELECT 1 FROM analytics_action_log WHERE status = ''recovered'' AND fired_at > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-10080 minutes'')) THEN ''the evaluator closed no recovered METRIC-TRIGGER issue in 7 days, so the TRIGGER-RECOVERY-1 path that the gate defers to is not running'' ELSE ''ok'' END AS observed'
WHERE control = 'metric-playbook-recovery-hold' AND probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''MD-4'' AND enabled = 1 AND instr(trigger_sql, ''* 1440 >= 120 AND'') > 0) THEN ''the MD-4 rule is missing, disabled or its recovery gate is no longer 120 minutes (the SLA-120M-1 ceiling)'' WHEN COALESCE((SELECT value FROM ops_config WHERE key = ''breach_doctor''), ''measure'') NOT IN (''on'', ''measure'', ''off'') THEN ''ops_config breach_doctor holds a value other than on, measure or off, so the lever that removes the gate without a deploy is unreadable'' WHEN NOT EXISTS (SELECT 1 FROM analytics_action_log WHERE status = ''recovered'' AND fired_at > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-10080 minutes'')) THEN ''the evaluator closed no recovered METRIC-TRIGGER issue in 7 days, so the TRIGGER-RECOVERY-1 path that the gate defers to is not running'' ELSE ''ok'' END AS observed';

UPDATE control_alternate_probes SET probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''PN-R2'') THEN ''the PN-R2 rule is missing, so the enabled switch that stops it has no row to switch'' WHEN EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''PN-R2'' AND (instr(trigger_sql, ''1440 minutes'') > 0 OR instr(trigger_sql, ''24 hours'') > 0)) THEN ''the PN-R2 trigger carries a 24-hour quiet window again, which SLA-120M-1 forbids'' WHEN EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''PN-R2'' AND instr(trigger_sql, ''BREACH-DOCTOR-1: PN-R2 qnfo-fleet-control'') = 0) THEN ''the PN-R2 trigger no longer reads the lever issue BREACH-DOCTOR-1: PN-R2 qnfo-fleet-control, so the gate has no release condition'' WHEN EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''PN-R2'' AND instr(verify_sql, ''pn-reopened'') = 0) THEN ''the PN-R2 verify no longer reads pn-reopened, so a close that the filer undoes is not counted'' ELSE ''ok'' END AS observed'
WHERE control = 'pn-r2-filer-quiet-gate' AND probe_sql = 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''PN-R2'' AND enabled = 1) THEN ''the PN-R2 rule is missing or disabled, so the enabled switch that stops it is not a lever'' WHEN EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''PN-R2'' AND instr(trigger_sql, ''1440'') > 0) THEN ''the PN-R2 trigger carries a 1440-minute window again, which SLA-120M-1 forbids'' WHEN EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''PN-R2'' AND instr(trigger_sql, ''BREACH-DOCTOR-1: PN-R2 qnfo-fleet-control'') = 0) THEN ''the PN-R2 trigger no longer reads the lever issue BREACH-DOCTOR-1: PN-R2 qnfo-fleet-control, so the gate has no release condition'' WHEN EXISTS (SELECT 1 FROM breach_playbooks WHERE rule_id = ''PN-R2'' AND instr(verify_sql, ''pn-reopened'') = 0) THEN ''the PN-R2 verify no longer reads pn-reopened, so a close that the filer undoes is not counted'' ELSE ''ok'' END AS observed';

UPDATE control_alternate_probes SET window_note = window_note || ' | CONTROL-ALT-PROBES-4D 2026-10-26: recalibrated after an independent review of the 18 probes against the loops they describe: a disabled playbook row is the documented lever and no longer reads as a failure (the clauses read that the row exists), the clauses that need the doctor tick are skipped while ops_config breach_doctor is off in any spelling the engine reads (off, 0, false, no, disabled), the research flags are read without case and space as the worker reads them, and the sync tick check is skipped while the target is legacy.'
WHERE control IN ('research-repo-archive-gate', 'research-repo-sync-switches', 'breach-doctor-caps', 'breach-doctor-taint-guard', 'breach-doctor-gap-measure', 'breach-doctor-gap-caps', 'breach-doctor-rearm-capacity', 'breach-doctor-auto-demotion', 'breach-doctor-tool-exclusion-rule', 'metric-playbook-recovery-hold', 'pn-r2-filer-quiet-gate') AND instr(window_note, 'CONTROL-ALT-PROBES-4D') = 0;

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'rem-a3-drills',
  'a probe on an alternate must stay green while the alternate is in use and red when it is broken, so a clause that reads the lever as a failure, or needs a loop that the lever has stopped, is a defect of the probe and is corrected to read what the code reads, not loosened until it passes',
  'CONTROL-ALT-PROBES-4D: eleven of the 18 probes of CONTROL-ALT-PROBES-4 recalibrated after an independent review: a disabled playbook row is not a failure, tick-dependent clauses are skipped while the doctor is off in any spelling the engine reads, the research flags are read without case and space, the sync tick check is skipped while the target is legacy, the MD-4 gate accepts 1 to 120 minutes, the PN-R2 quiet window is matched by its forms, and the tool-exclusion and gap-measure probes also read the surge guard and the measure mode',
  'review 2026-10-26 19:00-19:35Z against live qnfo-audit and the code: breach_playbooks enabled 0 of 24 rules today, doctor tick events 55 since 10:30Z with a largest gap of 11 minutes, breachDoctorTick returns before bdWriteMetrics when the doctor is off (bdConfig reads off, 0, false, no, disabled), floorFlag trims and lowercases, TL-R03-exclude trigger holds the surge guard at positions 3831 and 3853, MD-4 gate parses as 120, PN-R2 holds no 1440 or 24 hours text, the 18 probes all read ok on live. The offline suite migrations/control-alternate-probes4d.test.mjs breaks every changed clause and checks the old versus new reading over the unchanged worlds',
  'migration merged, the next 6-hourly drill reads the recalibrated probes',
  'eleven stored probe texts and eleven window notes in control_alternate_probes, one backup table, read by the drill only',
  'the Rollback header restores the eleven probe texts and removes the note (decision_log stays: append-only)',
  'using a documented lever (a rule disabled, the doctor switched off, the legacy target) no longer files a drill ticket against a working alternate, and two probes that could not fail now can',
  'no CHAOS-DRILL-FAILED-1 control issue is filed for a rule disabled on purpose, a doctor switched off or a legacy target in use, and the drill still files one when the surge guard, the gate, the measure mode or a lever row is lost',
  'none',
  'd1:qnfo-audit breach_playbooks, ops_config, control_alternate_probes (SELECT only), qnfo-fleet-control/worker.js bdConfig, breachDoctorTick, bdLoadRules, qnfo-research-exec/worker.js floorFlag, offline node:sqlite suite'
WHERE NOT EXISTS (SELECT 1 FROM decision_log WHERE instr(action, 'CONTROL-ALT-PROBES-4D:') = 1);
